"use strict";
(()=>{const {fmt,plane,arrow,text,line,vec}=LA;const control=document.getElementById('shear'),drawing=document.getElementById('drawing');if(!control||!drawing)return;
 function panel(cx,k,after){const {X,Y,axes}=plane({cx,cy:239,scale:47,extentX:3,extentY:3,xlabel:'x',ylabel:'y'});let out=axes;const pts=[[0,0],[1,0],[1+k,1],[k,1]].map(v=>[X(v[0]),Y(v[1])].join(',')).join(' ');out+=`<polygon points="${pts}" fill="${after?'#e5ef6870':'#345ce81a'}" stroke="${after?'#9aa510':'#345ce8'}" stroke-width="2"/>`;out+=`<defs><clipPath id="home-grid-${after?'after':'before'}"><rect x="${cx-142}" y="98" width="284" height="282"/></clipPath></defs><g clip-path="url(#home-grid-${after?'after':'before'})">`;for(let n=-2;n<=2;n++){out+=`<path d="M${X(n-3*k)},${Y(-3)}L${X(n+3*k)},${Y(3)}" stroke="${after?'#d966502e':'#345ce825'}" stroke-width="1.5"/>`;}out+='</g>';out+=arrow(X(0),Y(0),X(1+k),Y(1),after?'coral':'blue');out+=text(cx,48,after?'做完規則：原來的點去哪？':'先看原位：右 1、上 1','svg-title','middle');out+=text(cx,81,after?'新終點：'+vec([1+k,1]):'先向右 1 格，再向上 1 格','svg-label','middle');out+=text(cx,416,after?'底 1 × 高 1 = 面積 1':'藍色箭頭：右 1、上 1','svg-small','middle');return out;}
 function update(){const k=Number(control.value);document.getElementById('shear-value').textContent=fmt(k);document.getElementById('matrix-value').textContent='[1  '+fmt(k)+'; 0  1]';document.getElementById('result-primary').textContent=vec([1+k,1]);document.getElementById('result-secondary').textContent='1 平方格';drawing.innerHTML=panel(204,0,false)+panel(610,k,true)+arrow(385,167,427,167,'ink')+text(407,144,'照規則','svg-label','middle');document.getElementById('feedback').textContent=k===0?'右推量調成 0：每個點都不用動，右圖就和左圖一樣。':`看箭頭的終點：它原本右 1、上 1。因為高 1 格，現在再${k>0?"往右":"往左"} ${fmt(Math.abs(k))} 格，變成 ${vec([1+k,1])}。高度沒有變；這一格的底和高也還是 1，所以面積仍是 1。`;}
 LA.bind(['shear'],update,{shear:1});})();
